package com.bank.ratelimit.store;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Stands in for Redis: a SHARED store with an ATOMIC token-bucket consume.
// In production this is a Redis Lua script (read+refill+consume in one op).
public class RedisRateStore {
    // key -> [tokens, lastRefillNanos]; shared across all gateway instances.
    private final Map<String, double[]> buckets = new ConcurrentHashMap<>();
    private final double refillPerSecond;
    private final double capacity;

    public RedisRateStore(double refillPerSecond, double capacity) {
        this.refillPerSecond = refillPerSecond;
        this.capacity = capacity;
    }

    // ATOMIC: refill by elapsed time, then consume one token if available.
    // synchronized here models the atomicity a Redis Lua script guarantees.
    public synchronized boolean tryConsume(String key) {
        double[] state = buckets.computeIfAbsent(key,
                k -> new double[]{capacity, System.nanoTime()});
        long now = System.nanoTime();
        double elapsedSec = (now - state[1]) / 1_000_000_000.0;
        state[0] = Math.min(capacity, state[0] + elapsedSec * refillPerSecond);
        state[1] = now;
        if (state[0] >= 1.0) { state[0] -= 1.0; return true; }
        return false;
    }

    public double remainingTokens(String key) {
        double[] s = buckets.get(key);
        return s == null ? capacity : s[0];
    }
}
