package com.bank.ratelimit.limiter;

import com.bank.ratelimit.store.RedisRateStore;
import java.util.logging.Logger;

// Per-user limiter: builds the user key and consults the SHARED store.
public class DistributedRateLimiter {
    private static final Logger log = Logger.getLogger(DistributedRateLimiter.class.getName());
    private final RedisRateStore store;

    public DistributedRateLimiter(RedisRateStore store) { this.store = store; }

    // Keyed by USER + route so limits are per-user, not per-instance.
    public boolean allow(String userId, String route) {
        String key = "rate:user:" + userId + ":" + route;
        boolean allowed = store.tryConsume(key);
        if (!allowed) {
            log.warning(() -> "429 for user " + userId + " on " + route
                    + " (shared bucket empty across ALL instances)");
        }
        return allowed;
    }
}
