package com.bank.ratelimit.gateway;

import com.bank.ratelimit.limiter.DistributedRateLimiter;
import java.util.logging.Logger;

// One of N gateway instances — they ALL share the same DistributedRateLimiter store.
public class GatewayInstance {
    private static final Logger log = Logger.getLogger(GatewayInstance.class.getName());
    private final String instanceId;
    private final DistributedRateLimiter limiter;

    public GatewayInstance(String instanceId, DistributedRateLimiter limiter) {
        this.instanceId = instanceId;
        this.limiter = limiter;
    }

    // Returns true if admitted, false if rate-limited (429).
    public boolean handle(String userId, String route) {
        boolean allowed = limiter.allow(userId, route);
        if (allowed) {
            log.fine(() -> instanceId + " ADMIT user " + userId + " on " + route);
        }
        return allowed;
    }
}
