package com.bank.ratelimit;

import com.bank.ratelimit.gateway.GatewayInstance;
import com.bank.ratelimit.limiter.DistributedRateLimiter;
import com.bank.ratelimit.store.RedisRateStore;
import java.util.logging.*;

public class DistributedRateLimitDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(DistributedRateLimitDemo.class.getName());

        // ONE shared store (Redis) — refill 5/sec, burst capacity 10.
        RedisRateStore sharedStore = new RedisRateStore(5, 10);
        DistributedRateLimiter limiter = new DistributedRateLimiter(sharedStore);

        // THREE gateway instances all pointing at the SAME shared store.
        GatewayInstance gw1 = new GatewayInstance("gw-1", limiter);
        GatewayInstance gw2 = new GatewayInstance("gw-2", limiter);
        GatewayInstance gw3 = new GatewayInstance("gw-3", limiter);
        GatewayInstance[] instances = { gw1, gw2, gw3 };

        String user = "rajesh-SAV2001";
        String route = "transfers";

        // Rajesh fires 15 rapid transfers; the load balancer scatters them
        // across gw-1, gw-2, gw-3. The SHARED bucket (10) is the single limit.
        log.info("=== Rajesh: 15 rapid transfers across 3 gateway instances ===");
        int admitted = 0, blocked = 0;
        for (int i = 0; i < 15; i++) {
            GatewayInstance gw = instances[i % 3]; // round-robin across instances
            if (gw.handle(user, route)) admitted++; else blocked++;
        }
        log.info("Rajesh across all instances: admitted=" + admitted
                + " (burst cap 10), blocked(429)=" + blocked);
        log.info("KEY POINT: limit enforced GLOBALLY (10), not 3x (30) — shared Redis bucket");
        log.info("Remaining tokens in shared bucket: "
                + String.format("%.1f", sharedStore.remainingTokens("rate:user:" + user + ":" + route)));
    }
}

